frame_eqs_eel:
kick = max(bass - bass_att, 0);
pulse = max(pulse * 0.86, min(kick * 0.9, 1));
q3 = pulse;
pop = max(pop * 0.78, min(max(bass - 1.2, 0) * 0.55, 1.4));
q5 = pop;
depth = depth + 0.005 + 0.012 * min(bass_att, 2.5) + 0.03 * min(kick, 1.5) + 0.02 * pop;
twist = twist + 0.0015 + 0.003 * (mid_att - 1);
q1 = depth;
q2 = twist;
wave_r = NOKKVI_HIGHLIGHT_R;
wave_g = NOKKVI_HIGHLIGHT_G;
wave_b = NOKKVI_HIGHLIGHT_B;

comp:
uniform sampler2D sampler_fw_cover;
 shader_body {
  vec2 s = texsize.xy / min(texsize.x, texsize.y);
  vec2 p = (uv - 0.5) * s;
  p += vec2(0.07 * sin(time * 0.23), 0.06 * cos(time * 0.19));
  float r0 = max(length(p), 0.002);
  float a = atan(p.y, p.x);
  float r = r0 * (1.0 + 0.07 * sin(a * 3.0 + q1 * 1.7) * clamp(mid_att, 0.0, 2.0));
  r *= 1.0 + 0.10 * q3 + 0.08 * q5;
  float dep = 0.26 / r;
  vec2 t = vec2(a / 6.2831853 * 2.0 + q2 + 0.06 * dep, dep + q1);
  float cl = dot(texture(sampler_fw_cover, vec2(t.x, -t.y)).xyz, vec3(0.299, 0.587, 0.114));
  float lum = clamp((cl - 0.5) * 1.6 + 0.5, 0.0, 1.0);
  float col_r_x = clamp(lum, 0.0, 1.0) * 5.0;
  vec3 col_r = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(col_r_x, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP2, clamp(col_r_x - 1.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP3, clamp(col_r_x - 2.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP4, clamp(col_r_x - 3.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP5, clamp(col_r_x - 4.0, 0.0, 1.0));
  vec3 col = mix(NOKKVI_BG, col_r, smoothstep(0.02, 0.35, lum));
  col = mix(col, NOKKVI_TEXT, smoothstep(0.85, 1.0, lum) * 0.7);
  float band = pow(abs(sin((dep + q1) * 4.7123889)), 28.0);
  col += mix(NOKKVI_HIGHLIGHT, NOKKVI_TEXT, q3 * 0.5) * band * (0.25 + 0.9 * q3 + 0.8 * q5);
  col += NOKKVI_WARM * band * clamp(treb_att - 1.0, 0.0, 1.0) * 0.5;
  float fog = smoothstep(0.03, 0.42, r0);
  col = mix(NOKKVI_BG, col, fog * fog);
  col += NOKKVI_ACCENT * smoothstep(0.035, 0.0, abs(r0 - 0.07 - 0.05 * q3 - 0.04 * q5)) * (0.3 + 0.7 * q3 + 0.6 * q5);
  col *= 1.0 + 0.45 * q5;
  col += NOKKVI_ACCENT * GetBlur1(uv) * 0.9;
  col *= 0.85 + 0.15 * smoothstep(0.95, 0.3, r0);
  ret = col;
 }
